package main

import "fmt"

func maxSubarray(nums []int) int {
	// current is the best sum of a run that ends at the number you're on.
	current, best := nums[0], nums[0]
	for _, num := range nums[1:] {
		if current+num > num {
			current += num
		} else {
			current = num
		}
		if current > best {
			best = current
		}
	}
	return best
}

func main() {
	var n int
	fmt.Scan(&n)
	nums := make([]int, n)
	for i := range nums {
		fmt.Scan(&nums[i])
	}
	fmt.Println(maxSubarray(nums))
}

